function targetPreview(id){let a=canAct(),t=actor(id);if(!a||!t)return '';if(!t.enemy)return `${t.name}: ${t.hp}/${t.max} здоровья`;let spec=battleAction==='skill',s=a.hero?{power:1.4,type:['light','dark','fire','poison'][S.race]}:skill(a);let type=spec?s.type:a.category===3?['light','dark','fire','poison'][a.race]:'physical',n=estimateDamage(t,attackValue(a)*(spec?s.power:1),type,a.category===2?'arrow':'');let inter=type==='physical'&&a.category<2?teamOf(t).find(d=>d!==t&&canIntercept(d)&&adjacentSlots(d,t)):null;return `Ожидаемый урон до критического удара: ${n}. ${inter?'Перехват: '+inter.name+'. ':''}${protection(t).immune.includes(s.effect)?'Иммунитет к эффекту.':''}`;}
