function importRecord(file){let reader=new FileReader();reader.onload=()=>{try{let x=JSON.parse(reader.result),r=x.record;if(x.game!=='Пепельные земли'||!r||!Number.isInteger(r.days)||r.days<0)throw Error();let old=readRecord();if(!old||r.days>old.days)localStorage.setItem('ashen-record',JSON.stringify(r));note('Рекорд восстановлен из отчёта.');modalClose();}catch{uiNotice('Отчёт не содержит корректного рекорда.');}};reader.readAsText(file);}
