function repairEffects(u){for(let [key,e] of Object.entries(u.effects)){if(!e||typeof e!=='object'){delete u.effects[key];continue;}e.turns=Math.max(1,finite(e.turns,1));e.power=Math.max(0,finite(e.power,5));}}
function isLargeDemon(u){return u.race===2&&(u.tier>=2&&u.category===0||u.tier===3&&u.category===1);}
