 const d=$('modal');d.innerHTML='<div class="modal-header"><b>Пепельные земли</b><button type="button" class="modal-close" aria-label="Закрыть окно" onclick="modalClose()">✕ Закрыть</button></div><div class="modal-content">'+html+'</div><div class="modal-footer"><button type="button" onclick="modalClose()">Закрыть</button></div>';
