  timer=null;if(!B||B.id!==battleId||B.current!==current||B.phase!=='enemy-pending'||isModalOpen())return;
  const u=actor(current);if(!u){advance();return;}
  B.phase='resolving';enemyAction(u);if(check())return;finishActor(u);if(check())return;
